const games=[{id:'last-train',title:'Сүүлчийн галт тэрэг',en:'THE LAST\nTRAIN',genre:'Нууцлаг',image:'train.jpg',price:19900,desc:'Шөнө дундын сүүлчийн галт тэргэнд суусан ч буух буудал тань алга. Зорчигчдын нууцыг тайлж, хэнд итгэхээ өөрөө шийд.',length:'3–4 цаг'},{id:'neon',title:'Неон шөнийн нууц',en:'NEON\nNIGHTS',genre:'Драм',image:'city.webp',price:24900,desc:'Хот унтсан ч зарим түүх дөнгөж эхэлдэг. Нэг зурвас таныг өнгөрсөн амьдралынхаа тайлагдаагүй нууц руу хөтөлнө.',length:'4–5 цаг'},{id:'horizon',title:'Тэнгэрийн хаяа',en:'BEYOND THE\nHORIZON',genre:'Адал явдал',image:'mountain.jpg',price:14900,desc:'Танил бүхнээ орхиод үл мэдэх замд гар. Аяллын турш таарах хүмүүс, таны сонголтууд хүрэх газрыг өөрчилнө.',length:'2–3 цаг'}];
let owned=new Set(),filter='Бүгд',query='';const main=document.querySelector('main'),dialog=document.querySelector('dialog');
const money=n=>n.toLocaleString('en-US')+' ₮';
function card(g){return `<article class="card"><button class="cover" data-game="${g.id}" aria-label="${g.title} дэлгэрэнгүй"><img src="${g.image}" alt="${g.title} — жишээ нүүр зураг"><span class="badge">${owned.has(g.id)?'МИНИЙ САН':'ЖИШЭЭ ТОГЛООМ'}</span><span class="cover-title">${g.en.replace('\n','<br>')}</span></button><div class="card-info"><div><h3>${g.title}</h3><p>${g.genre} · Визуал новел</p></div><span class="price">${owned.has(g.id)?'Нэмэгдсэн':money(g.price)}</span></div></article>`}
function render(){let lib=location.hash==='#library';document.querySelector('#store-link').classList.toggle('active',!lib);document.querySelector('#library-link').classList.toggle('active',lib);document.querySelector('#count').textContent=owned.size;if(lib){main.innerHTML=`<div class="library-heading"><div class="eyebrow">ТАНЫ ТҮҮХҮҮД</div><h1>Миний сан</h1><p>Энэ туршилтын үеэр нэмсэн тоглоомууд. Хуудсыг шинэчлэхэд сан хоосорно.</p></div>${owned.size?'<div class="grid">'+games.filter(g=>owned.has(g.id)).map(card).join('')+'</div>':'<div class="empty"><h2>Шинэ түүх таныг хүлээж байна</h2><p>Дэлгүүрээс жишээ тоглоом сонгож, сандаа нэмээд үзээрэй.</p><a class="btn" href="#store">Дэлгүүр үзэх</a></div>'}`;return}main.innerHTML=`<section class="hero"><img src="train.jpg" alt="Манантай төмөр зам"><div class="hero-content"><div class="eyebrow">ОНЦЛОХ ТҮҮХ / 01</div><h1>Сүүлчийн<br>галт тэрэг.</h1><div class="tags"><span>Нууцлаг</span><span>Визуал новел</span><span>Монгол хэл</span></div><p>Буух буудал бүр нэг нууц.<br>Төгсгөлийг таны сонголт шийднэ.</p><button class="btn" data-game="last-train">Тоглоомтой танилцах <span>＋</span></button><div class="hero-note">Бүтэн тоглоом · Жишээ үнэ ${money(games[0].price)}</div></div><div class="hero-bottom" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="section-top"><div><h2>Дараагийн түүхээ сонго</h2><p>Монгол хэл дээрх визуал новелууд</p></div><input class="search" type="search" placeholder="Тоглоом хайх…" aria-label="Тоглоом хайх"></div><div class="filters">${['Бүгд','Нууцлаг','Драм','Адал явдал'].map(t=>`<button class="chip ${t===filter?'active':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="grid" id="catalog"></div><div class="subnote"><span>WEB · ANDROID · iOS — Төлөвлөж буй платформууд</span><span>Бүтэн тоглоом. Нэг удаагийн худалдан авалт.</span></div>`;main.querySelector('input').value=query;catalog()}
function catalog(){const list=games.filter(g=>(filter==='Бүгд'||g.genre===filter)&&g.title.toLowerCase().includes(query.toLowerCase()));document.querySelector('#catalog').innerHTML=list.length?list.map(card).join(''):'<p>Тохирох тоглоом олдсонгүй. Өөр нэрээр хайгаарай.</p>'}
function showGame(id){const g=games.find(g=>g.id===id);if(!g)throw Error('Тоглоом олдсонгүй');document.querySelector('#dialog-content').innerHTML=`<img class="detail-image" src="${g.image}" alt="${g.title}"><div class="detail-body"><div class="eyebrow">${g.genre} · ВИЗУАЛ НОВЕЛ</div><h2>${g.title}</h2><p>${g.desc}</p><div class="detail-facts"><div><span>Хэл</span>Монгол</div><div><span>Жишээ хугацаа</span>${g.length}</div><div><span>Хувилбар</span>Бүтэн тоглоом</div></div><p class="notice">Энэ бол жишээ тоглоомын хуудас. Үнэ, тайлбар, зураг нь загвар үзүүлэх зориулалттай. Бодит төлбөр авахгүй, Ren’Py тоглоом хараахан холбогдоогүй.</p><div class="purchase-row"><strong>${money(g.price)}</strong><button class="btn" id="purchase" data-id="${g.id}">${owned.has(g.id)?'Санд нэмэгдсэн ✓':'Худалдан авахыг турших'}</button></div>${owned.has(g.id)?'<p>Тоглох боломжийг бодит тоглоомын файл холбосны дараа нээнэ.</p>':''}</div>`;if(!dialog.open)dialog.showModal()}
function checkout(id){const g=games.find(g=>g.id===id);if(!g)return;if(owned.has(id)){dialog.close();location.hash='library';return}document.querySelector('#dialog-content').innerHTML=`<div class="detail-body"><div class="eyebrow">ТУРШИЛТЫН ЗАХИАЛГА</div><h2>Захиалгаа шалгах</h2><p>${g.title} · Бүтэн тоглоом</p><div class="detail-facts"><div><span>Нийт жишээ дүн</span><strong>${money(g.price)}</strong></div></div><p class="notice">Мөнгө суутгахгүй. Баталгаажуулахад тоглоом зөвхөн энэ хуудсын туршилтын санд нэмэгдэнэ. Бүртгэл болон бодит төлбөрийн холболт дараагийн шатанд хийгдэнэ.</p><div class="purchase-row"><button class="btn secondary" data-game="${g.id}">Буцах</button><button class="btn" id="confirm" data-id="${g.id}">Туршилтаар сандаа нэмэх</button></div></div>`}
document.addEventListener('click',e=>{let game=e.target.closest('[data-game]');if(game)showGame(game.dataset.game);let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render()}if(e.target.closest('.close'))dialog.close();if(e.target.closest('#purchase'))checkout(e.target.closest('#purchase').dataset.id);if(e.target.closest('#confirm')){owned.add(e.target.closest('#confirm').dataset.id);dialog.close();render();const t=document.querySelector('#toast');t.textContent='Туршилтын санд нэмэгдлээ';t.style.display='block';setTimeout(()=>t.style.display='none',3000)}});main.addEventListener('input',e=>{if(e.target.matches('.search')){query=e.target.value;catalog()}});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_game_details',description:'Open demo catalog game details. Does not purchase or add it to the library.',inputSchema:{type:'object',properties:{gameId:{type:'string',enum:games.map(g=>g.id)}},required:['gameId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({gameId})=>{showGame(gameId);return {opened:gameId}}})).catch(()=>{})}catch{}}
